import json
import time
from collections import deque

start = time.monotonic()
deadline = start + 4.5

categories = {
    "team": [
        "Philadelphia Eagles", "Kansas City Chiefs", "Miami Dolphins",
        "Baltimore Ravens", "Dallas Cowboys", "Atlanta Falcons",
        "Arizona Cardinals", "Los Angeles Rams"
    ],
    "motorbike": [
        "Ducati", "Bajaj", "Yamaha", "Benelli",
        "Kawasaki", "Buell", "Suzuki", "Honda"
    ],
    "name": [
        "Michelle", "Mandy", "Rajiv", "Ali",
        "Mallika", "Wang", "Mohsen", "Jones"
    ],
    "house": [
        "pink", "teal", "gold", "violet",
        "magenta", "turquoise", "grey", "beige"
    ],
    "activity": [
        "hiking", "weight lifting", "paragliding", "scuba diving",
        "base jumping", "running", "swimming", "snorkeling"
    ],
    "handbag": [
        "Dolce and Gabbana", "Versace", "Balenciaga", "Coach",
        "Gucci", "Tumi", "Polo Ralph Lauren", "Michael Kors"
    ],
    "gemstone": [
        "Pearls", "Sapphires", "Corals", "Diamonds",
        "Aquamarines", "Obsidians", "Moonstones", "Emeralds"
    ],
    "books": [
        "history", "mystery", "short story", "fantasy",
        "magical realism", "romance", "science fiction", "humor"
    ]
}

labels = [value for values in categories.values() for value in values]
parent = {x: x for x in labels}

def root(x):
    while parent[x] != x:
        parent[x] = parent[parent[x]]
        x = parent[x]
    return x

def unite(a, b):
    a, b = root(a), root(b)
    if a != b:
        parent[b] = a

equalities = [
    ("swimming", "Ducati"),                      # 4
    ("Dallas Cowboys", "turquoise"),             # 9
    ("magenta", "Corals"),                       # 16
    ("running", "Dallas Cowboys"),               # 18
    ("Ali", "running"),                          # 20
    ("Wang", "scuba diving"),                    # 22
    ("base jumping", "science fiction"),         # 29
    ("Jones", "Philadelphia Eagles"),            # 30
    ("Miami Dolphins", "Obsidians"),             # 36
    ("Buell", "Polo Ralph Lauren"),              # 37
    ("Atlanta Falcons", "scuba diving"),         # 38
    ("Gucci", "Pearls"),                         # 40
    ("Benelli", "Kansas City Chiefs"),           # 45
    ("Pearls", "Ducati"),                        # 49
    ("Atlanta Falcons", "magical realism"),      # 50
]
for a, b in equalities:
    unite(a, b)

roots = sorted({root(x) for x in labels})
index = {r: i for i, r in enumerate(roots)}
var = {x: index[root(x)] for x in labels}
n = len(roots)
FULL = 255
domains = [FULL] * n
groups = [[var[x] for x in values] for values in categories.values()]
relations = {}
inconsistent = False

def relation(a, b, predicate):
    global inconsistent
    x, y = var[a], var[b]
    if x == y:
        allowed = sum(1 << p for p in range(8) if predicate(p, p))
        domains[x] &= allowed
        return
    if x > y:
        x, y = y, x
        original = predicate
        predicate = lambda p, q: original(q, p)
    rows = tuple(
        sum(1 << q for q in range(8) if predicate(p, q))
        for p in range(8)
    )
    key = (x, y)
    if key in relations:
        rows = tuple(a & b for a, b in zip(relations[key], rows))
    relations[key] = rows

def left(a, b):
    relation(a, b, lambda p, q: p + 1 == q)

def before(a, b):
    relation(a, b, lambda p, q: p < q)

def next_to(a, b):
    relation(a, b, lambda p, q: abs(p - q) == 1)

def fixed(a, position):
    domains[var[a]] &= 1 << (position - 1)

def end(a):
    domains[var[a]] &= 129

# Every category is a permutation of positions 1 through 8.
for group in groups:
    if len(set(group)) != 8:
        inconsistent = True
    for i in range(8):
        for j in range(i + 1, 8):
            relation(roots[group[i]], roots[group[j]], lambda p, q: p != q)

left("Kansas City Chiefs", "Emeralds")           # 1
left("Michael Kors", "Gucci")                   # 2
left("Moonstones", "turquoise")                 # 3
next_to("hiking", "Aquamarines")                # 5
end("snorkeling")                              # 6
relation("Buell", "Versace", lambda p, q: p != q)  # 7
next_to("Baltimore Ravens", "humor")            # 8
