before("science fiction", "short story")        # 44
left("base jumping", "Emeralds")                # 46
left("history", "Baltimore Ravens")             # 47
left("Dolce and Gabbana", "Balenciaga")          # 48

def union_table(rows):
    table = [0] * 256
    for mask in range(1, 256):
        bit = mask & -mask
        table[mask] = table[mask ^ bit] | rows[bit.bit_length() - 1]
    return table

adjacency = [[] for _ in range(n)]
for (x, y), rows in relations.items():
    reverse = tuple(
        sum(1 << p for p in range(8) if rows[p] & (1 << q))
        for q in range(8)
    )
    adjacency[x].append((y, union_table(rows)))
    adjacency[y].append((x, union_table(reverse)))

class Timeout(Exception):
    pass

def check_time():
    if time.monotonic() >= deadline:
        raise Timeout

def propagate(d, changed):
    queue = deque(changed)
    queued = set(changed)

    def restrict(v, mask):
        new = d[v] & mask
        if not new:
            return False
        if new != d[v]:
            d[v] = new
            if v not in queued:
                queue.append(v)
                queued.add(v)
        return True

    while True:
        check_time()
        while queue:
            x = queue.popleft()
            queued.remove(x)
            if not d[x]:
                return False
            for y, table in adjacency[x]:
                if not restrict(y, table[d[x]]):
                    return False

        for group in groups:
            coverage = 0
            for v in group:
                coverage |= d[v]
            if coverage != FULL:
                return False
            for p in range(8):
                bit = 1 << p
                owners = [v for v in group if d[v] & bit]
                if len(owners) == 1 and not restrict(owners[0], bit):
                    return False

            # A set of k identical k-position domains occupies those positions.
            counts = {}
            for v in group:
                mask = d[v]
                counts.setdefault(mask, []).append(v)
            for mask, owners in counts.items():
                size = mask.bit_count()
                if len(owners) > size:
                    return False
                if len(owners) == size and size < 8:
                    owner_set = set(owners)
                    for v in group:
                        if v not in owner_set and not restrict(v, FULL ^ mask):
                            return False
        if not queue:
            return True

def solve(d, changed):
    if not propagate(d, changed):
        return None
    candidates = [v for v in range(n) if d[v].bit_count() > 1]
    if not candidates:
        return d
    v = min(candidates, key=lambda x: (d[x].bit_count(), -len(adjacency[x])))
    choices = d[v]
    while choices:
        check_time()
        bit = choices & -choices
        choices ^= bit
        child = d.copy()
        child[v] = bit
        answer = solve(child, [v])
        if answer is not None:
            return answer
    return None

try:
    possible = []
    witness = None
    if not inconsistent and propagate(domains, range(n)):
        for position in range(1, 9):
            check_time()
            bit = 1 << (position - 1)
            if not domains[var["Rajiv"]] & bit:
                continue
            trial = domains.copy()
            trial[var["Rajiv"]] = bit
            solution = solve(trial, [var["Rajiv"]])
            if solution is not None:
                possible.append(position)
                if witness is None:
                    witness = solution

    evidence = {
        "possible_Rajiv_positions": possible,
        "method": "Exact finite-domain search; feasibility checked for all 8 positions."
    }
    if len(possible) == 1:
        rows = []
        for position in range(1, 9):
            bit = 1 << (position - 1)
            rows.append([
                next(x for x in values if witness[var[x]] == bit)
                for values in categories.values()
            ])
        evidence["witness_columns"] = list(categories)
        evidence["witness_rows_positions_1_to_8"] = rows
        final_answer = str(possible[0])
    elif possible:
        final_answer = "Not uniquely determined"
    else:
        final_answer = "No arrangement satisfies all clues"

    print(json.dumps({"final_answer": final_answer, "evidence": evidence},
                     separators=(",", ":")))
except Timeout:
    print("UNSUPPORTED")
